package httpserver

import (
	"io"
	"net/http"
)

func renderProjectOverview(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, projectDemoPage)
}

func projectDemoScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, projectDemoJavaScript)
}

const projectDemoPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>项目工作空间</title><style>` + projectDemoCSS + `.nav-link{display:block;padding:11px 16px;color:var(--accent);font-size:13px;font-weight:700;text-decoration:none}.nav-link:hover{background:#f3f6fa}#assignmentManualMode{width:auto;padding:0;margin:0 7px 0 0;vertical-align:middle}#assignmentDirectory>label{display:grid;gap:6px;margin-top:12px}.list-panel .panel-head{flex-direction:column;align-items:stretch;gap:10px}.list-panel .button-row{flex-wrap:wrap}.list-panel .button-row button{flex:none;white-space:nowrap}.capability-inspector{margin:10px 0 14px;color:var(--muted);font-size:12px}.capability-inspector summary{cursor:pointer}.capability-inspector .action-chips{margin-top:8px}[hidden]{display:none!important}</style></head><body>
<header class="top"><a class="brand" href="./"><span>PW</span><strong>项目工作空间</strong></a><div class="credential"><span id="credentialState">尚未连接</span><button id="refreshPermissions" class="quiet">刷新权限</button><button id="openCredential" class="quiet">设置访问凭证</button></div></header>
<div class="layout"><aside class="rail"><p class="rail-label">工作区</p><button class="nav active" data-view="overview">概览</button><button class="nav" data-view="records">项目台账</button><a class="nav-link" href="completion/">C5 完成检查点</a><div class="rail-note"><strong>独立业务应用</strong><span>Project 拥有自己的事实、修订与历史；IAM 决定谁能做什么。</span></div></aside>
<main>
 <section id="overview" class="view active"><div class="hero"><p class="eyebrow">Project Workspace</p><h1>让立项从一张表，变成可追溯的业务事实。</h1><p>建立项目，引用 People &amp; Groups 中的负责人，连接合同或资金记录，并将多个独立项目按需装入项目包。页面只展示服务端确认的可用动作。</p><button class="primary" data-go="records">进入项目台账</button></div><div class="flow"><article><b>01</b><h2>建立项目</h2><p>项目编号、名称、类型与计划周期形成 draft。</p></article><article><b>02</b><h2>装配责任</h2><p>用稳定 Person / Group ID 引用业务与生产负责人。</p></article><article><b>03</b><h2>按需组合</h2><p>项目包只增加层级，不改写项目 ID、业务事实与历史。</p></article></div></section>
 <section id="records" class="view"><div class="section-head"><div><p class="eyebrow">项目台账</p><h1>项目与立项工作区</h1></div><button id="refresh" class="quiet">刷新数据</button></div>
  <div id="notice" class="notice">请先设置访问凭证，再读取受保护的项目数据。</div>
  <aside id="accessRecovery" class="recovery" hidden><div><strong>权限上下文已经变化</strong><span>页面已退出可编辑状态。刷新权限后再继续；若已撤权，将只保留仍被允许的动作。</span></div><a href="../workbench/">返回统一工作台</a></aside>
  <div class="records-grid"><section class="panel list-panel"><div class="panel-head"><h2>项目与项目包</h2><div class="button-row"><button id="newPackage" class="quiet">新建项目包</button><button id="newProject" class="primary">新建项目</button></div></div><details class="capability-inspector"><summary>查看当前可用动作</summary><div id="listActions" class="action-chips"></div></details><div id="projectList" class="record-list"><div class="empty">连接后显示最近项目。</div></div></section>
  <section class="panel workspace"><div id="workspaceEmpty" class="empty large"><strong>选择一个项目或项目包</strong><span>查看负责人、资源连接、层级和历史；可用动作由 IAM 凭证与当前状态共同决定。</span></div>
   <div id="workspaceContent" hidden><div class="workspace-head"><div><div class="title-line"><span id="projectKind" class="kind"></span><span id="projectStatus" class="status"></span></div><h2 id="projectName"></h2><code id="projectIdentity"></code><details class="capability-inspector"><summary>查看当前项目可用动作</summary><div id="detailActions" class="action-chips"></div></details></div><button id="reloadProject" class="quiet">重新载入</button></div>
    <dl class="facts"><div><dt>摘要</dt><dd id="projectSummary"></dd></div><div><dt>修订</dt><dd id="projectRevision"></dd></div><div><dt>类型</dt><dd id="projectTypes"></dd></div><div><dt>立项客户快照</dt><dd id="projectClient"></dd></div></dl>
    <div class="workspace-tabs"><button class="subnav active" data-pane="responsibility">负责人</button><button class="subnav" data-pane="resources">资源连接</button><button class="subnav" data-pane="materials">项目资料</button><button class="subnav" data-pane="commercial">经营链路</button><button class="subnav" data-pane="package">项目包</button><button class="subnav" data-pane="history">历史</button></div>
    <section id="responsibility" class="pane active"><div class="pane-head"><h3>责任装配</h3><span>完成立项需要经营负责人和生产负责人。</span></div><div id="assignmentList" class="compact-list"></div><form id="assignmentForm" class="form-grid"><label>角色<select name="role_key"><option value="business_owner">经营负责人</option><option value="production_owner">生产负责人</option><option value="participant">参与者</option></select></label><label>主体类型<select name="subject_kind"><option value="person">人员</option><option value="group">编组</option></select></label><div id="assignmentDirectory" class="wide"><div class="client-controls"><label>搜索人员或编组<input id="assignmentSearch" type="search" placeholder="姓名、名称或引用码" autocomplete="off"></label><button id="loadAssignmentCandidates" type="button" class="quiet">加载人员目录</button></div><label>选择负责人<select id="assignmentCandidate" required><option value="">请先加载目录</option></select></label><p id="assignmentReferenceFeedback" class="permission-note" role="status" aria-live="polite">从 People &amp; Groups 选择；提交时会再次核对来源版本。</p></div><label class="wide"><span><input id="assignmentManualMode" type="checkbox">高级：手动输入 ID 与版本（引用排查）</span></label><label class="wide assignment-manual" hidden>Person / Group ID<input name="subject_id" placeholder="稳定 UUID"></label><label class="assignment-manual" hidden>来源 revision<input name="source_revision" type="number" min="1" value="1"></label><button id="submitAssignment" class="primary" type="submit" disabled>添加负责人</button></form><p id="assignmentDenied" class="permission-note" hidden>当前权限只能查看负责人，不能调整责任。</p><button id="completeProject" class="primary action-wide">检查缺口并完成立项</button></section>
    <section id="resources" class="pane"><div class="pane-head"><h3>资源连接</h3><span>这里只保存目标 ID 与 revision，不读取目标应用内部表。</span></div><div id="resourceList" class="compact-list"></div><form id="resourceForm" class="form-grid"><label>目标应用<select name="target_service"><option value="contract-ledger">合同台账</option><option value="money-flow-ledger">资金台账</option><option value="billing-invoice">开票登记</option><option value="evidence-service">Evidence 资料</option><option value="business-engagement">业务承接资料源</option><option value="production-operations">生产资料源</option><option value="approval-audit-results">批复审计资料源</option><option value="cost-outsourcing">成本外协资料源</option></select></label><label>资源类型<select name="resource_type"><option value="contract">contract</option></select></label><label class="wide">资源 ID<input name="resource_id" required placeholder="目标资源 UUID"></label><label>来源 revision<input name="source_revision" type="number" min="1" value="1"></label><label>关系键<input name="relation_key" value="primary-contract" required></label><button class="primary" type="submit">建立连接</button></form><p id="resourceDenied" class="permission-note" hidden>当前权限只能查看资源连接。</p></section>
    <section id="materials" class="pane"><div class="pane-head"><div><h3>项目资料</h3><span>Project 只读取文件元数据；下载必须另行取得 Evidence 的精确授权。</span></div><button id="refreshMaterials" class="quiet">重新读取</button></div><div id="materialMeta" class="commercial-meta">切换到本页后读取。</div><div id="materialList" class="commercial-grid"></div><p id="materialDenied" class="permission-note" hidden>当前凭证没有读取项目资料的能力；刷新权限后，已撤销的入口不会继续显示。</p></section>
    <section id="commercial" class="pane"><div class="pane-head"><div><h3>项目经营链路</h3><span>实时并行读取合同、义务／资金和开票事实；某一来源失败不会伪装成 0，也不会阻断其他分段。</span></div><button id="refreshCommercial" class="quiet">重新读取</button></div><div id="commercialMeta" class="commercial-meta">切换到本页后读取。</div><div id="commercialList" class="commercial-grid"></div></section>
    <section id="package" class="pane"><div class="pane-head"><h3>项目包与层级</h3><span>组合只增加父子关系；项目事实、ID 与历史保持不变。</span></div><div id="hierarchySummary" class="hierarchy"></div><form id="conversionForm" class="form-grid" hidden><label>组合方式<select name="operation"><option value="attach_existing">加入已有项目包</option><option value="wrap_as_package">新建外层项目包</option></select></label><label>排序<input name="sort_order" type="number" min="0" value="10" required></label><label class="wide attach-field">目标项目包<select name="target_package_id"></select></label><label class="wide wrap-field" hidden>新项目包名称<input name="package_name" placeholder="例如：华东项目包"></label><label class="wrap-field" hidden>项目包编号（可空）<input name="package_number" placeholder="例如：PKG-2026-01"></label><label class="wrap-field" hidden>项目包类型<input name="package_types" value="design"></label><button class="primary" type="submit">确认组合</button></form><div id="rollbackBox" class="danger-zone" hidden><div><strong>撤销最近一次项目包转换</strong><span>仅在项目包没有新增子项、项目和项目包 revision 均未继续变化时允许。</span></div><button id="openRollback" class="danger">高风险：撤销组合</button></div><p id="hierarchyDenied" class="permission-note" hidden>当前权限只能查看层级，不能创建、组合或撤销项目包。</p></section>
    <section id="history" class="pane"><div class="pane-head"><h3>变更历史</h3><button id="loadHistory" class="quiet">读取历史</button></div><div id="historyList" class="timeline"></div><p id="historyDenied" class="permission-note" hidden>当前凭证没有读取历史的能力。</p></section>
   </div>
  </section></div>
 </section>
</main></div>
<dialog id="credentialDialog"><form method="dialog" id="credentialForm"><p class="eyebrow">访问控制</p><h2>连接受保护业务 API</h2><p>本地开发可粘贴模板 Token，正式环境由 Gateway 使用 IAM 会话换取短期 Capability Credential。Token 只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button type="button" data-cancel-dialog class="quiet">取消</button><button value="default" class="primary">保存并连接</button></div></form></dialog>
<dialog id="createDialog"><form method="dialog" id="createForm"><p class="eyebrow">新建</p><h2>建立 Project</h2><label>项目编号<input name="project_number" required placeholder="DEMO-2026-001"></label><label>项目名称<input name="name" required placeholder="示范设计项目"></label><label>摘要<textarea name="summary" rows="3" placeholder="一句话说明项目目标"></textarea></label><div class="form-grid"><label>开始日期<input name="planned_start_date" type="date"></label><label>结束日期<input name="planned_end_date" type="date"></label></div><label>项目类型<input name="project_type_keys" value="design" required><small>多个类型用逗号分隔</small></label><section class="client-choice"><div><strong>客户主体（可选）</strong><small>需要时从 Party Directory 选择；立项只保存当时的 ID、revision 与名称快照。</small></div><div class="client-controls"><select name="client_party"><option value="">不选择客户主体（Base 可独立立项）</option></select><button id="loadClientParties" type="button" class="quiet">加载主体目录</button></div><p id="clientPartyFeedback" class="permission-note">未选择主体不会阻塞 Base Project；本轮不提供立项后的改绑或解绑。</p></section><div class="dialog-actions"><button type="button" data-cancel-dialog class="quiet">取消</button><button value="default" class="primary">建立项目</button></div></form></dialog>
<dialog id="packageDialog"><form method="dialog" id="packageForm"><p class="eyebrow">新建</p><h2>建立独立项目包</h2><p>项目包是可选的业务容器，不复制或接管子项目事实。</p><label>项目包名称<input name="name" required placeholder="例如：年度设计项目包"></label><label>项目包编号（可空）<input name="project_number" placeholder="例如：PKG-2026"></label><label>摘要<textarea name="summary" rows="3"></textarea></label><label>项目包类型<input name="project_type_keys" value="design" required></label><div class="dialog-actions"><button type="button" data-cancel-dialog class="quiet">取消</button><button value="default" class="primary">建立项目包</button></div></form></dialog>
<dialog id="rollbackDialog"><form method="dialog" id="rollbackForm"><p class="eyebrow danger-text">高风险动作</p><h2>确认撤销项目包组合</h2><p>系统会再次核对 project/package revision 与新增业务事实。已发生后续变化时不会自动撤销。</p><label>撤销原因<textarea name="reason" rows="3" required placeholder="说明为什么需要恢复原来的独立项目"></textarea></label><div class="dialog-actions"><button type="button" data-cancel-dialog class="quiet">取消</button><button value="default" class="danger">确认撤销</button></div></form></dialog>
<script src="assets/demo.js"></script></body></html>`

